// Apenas para testes administrativos com exemplos fixos e sem dados pessoais.
export function initAiWritingDemo({container,getState,onChange}){
 const box=document.createElement('details');box.className='ai-writing-demo options-panel';box.hidden=true;box.innerHTML='<summary>Experimentar sugestão com IA</summary><p>Teste administrativo com temas fictícios. Nenhum nome, foto ou texto do presente é enviado. A IA pode errar: revise antes de usar.</p><label>Exemplo<select class="ai-writing-theme"><option value="texto_aniversario">Aniversário de amizade</option><option value="texto_namoro">Namoro</option><option value="texto_familia">Família</option></select></label><label>Tom<select class="ai-writing-tone"><option value="carinhoso">Carinhoso</option><option value="alegre">Alegre</option><option value="simples">Simples e direto</option><option value="emocionante">Emocionante</option></select></label><label>Formato<select class="ai-writing-format"><option value="cartao">Cartão</option><option value="livro">Livro</option><option value="convite">Convite</option><option value="stories">Stories</option></select></label><label>Aplicar em<select class="ai-writing-target"><option value="message">Mensagem do presente</option><option value="letter">Carta</option></select></label><button type="button" class="ai-writing-generate">Gerar sugestão</button><p class="ai-writing-status" role="status"></p><div class="ai-writing-result" hidden><p class="ai-writing-text"></p><button type="button" class="ai-writing-apply">Usar esta sugestão</button></div>';container.append(box);
 const nameLabel=document.createElement('label');nameLabel.textContent='Nome ou apelido (opcional, acrescentado no seu aparelho)';const nameInput=document.createElement('input');nameInput.className='ai-writing-name';nameInput.maxLength=40;nameInput.autocomplete='off';nameLabel.append(nameInput);box.querySelector('.ai-writing-target').parentElement.before(nameLabel);
 const $=s=>box.querySelector(s),status=$('.ai-writing-status'),result=$('.ai-writing-result'),output=$('.ai-writing-text'),generate=$('.ai-writing-generate');let version=0,view='',suggestion='',generatedFor='';
 const context=()=>JSON.stringify([getState().draftId||'',getState().format||'']);
 function render(){const next=context();if(next!==view){view=next;nameInput.value='';const format=getState().format;if(['cartao','livro','convite','stories'].includes(format))$('.ai-writing-format').value=format;version++;suggestion='';generatedFor='';result.hidden=true;status.textContent='';generate.disabled=false;}}
 for(const selector of ['.ai-writing-theme','.ai-writing-tone','.ai-writing-format','.ai-writing-target','.ai-writing-name'])$(selector).addEventListener(selector==='.ai-writing-name'?'input':'change',()=>{version++;suggestion='';generatedFor='';result.hidden=true;status.textContent='';generate.disabled=false;});
 generate.addEventListener('click',async()=>{const own=++version,started=context(),selection=$('.ai-writing-theme').value,target=$('.ai-writing-target').value;generate.disabled=true;result.hidden=true;suggestion='';status.textContent='Criando sugestão…';try{const response=await fetch('/api/admin/ai-demo',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({selection,tone:$('.ai-writing-tone').value,format:$('.ai-writing-format').value,target})});const data=await response.json();if(!response.ok)throw Error(data.error||'Não foi possível gerar agora.');if(own!==version||started!==context())return;const answer=typeof data.answer==='string'?data.answer.trim():'';const name=nameInput.value.trim();const text=answer?(name?name+' — '+answer:answer):'';const max=target==='message'?180:2000;if(!text||text.length>max)throw Error('A sugestão ficou longa demais. Gere outra para manter o texto completo.');suggestion=text;generatedFor=started;output.textContent=text;result.hidden=false;status.textContent='Sugestão pronta. Leia e escolha se deseja usar.';}catch(error){if(own===version&&started===context())status.textContent=error.message||'Não foi possível gerar agora.';}finally{if(own===version)generate.disabled=false;}});
 $('.ai-writing-apply').addEventListener('click',()=>{if(!suggestion||generatedFor!==context())return;const target=$('.ai-writing-target').value,state=getState(),existing=target==='message'?state.message:state.experience?.letter;if(existing?.trim()&&!confirm('Substituir o texto atual por esta sugestão?'))return;if(target==='message')onChange({message:suggestion});else onChange({experience:{...state.experience,letter:suggestion}});status.textContent='Sugestão aplicada. Você pode editar o texto.';result.hidden=true;suggestion='';});
 fetch('/api/admin/session',{credentials:'same-origin',cache:'no-store'}).then(r=>r.ok?r.json():null).then(data=>{if(data?.authenticated)box.hidden=false;}).catch(()=>{});render();return {render};
}
